"""
    encode given `value` as sexagesimal string

    :param float value:  declination in decimal degrees
    :return str: sring in sexagesmial form

    """
def deg2dec(value: Any) -> object {
    value = round(value, 5);
    sign = 1;
    if (value < 0) {
        sign = -1;
        value = abs(value);
    }
    (dd, r1) = divmod(value, 1);
    (mm, r2) = divmod((r1 * 60), 1);
    ss = r2 * 60;
    return "{0:+03d}:{1:02d}:{2:05.2f}".format(int((sign * dd)), int(mm), ss);
}

""" Helping function which returns None or the href attribute.

    Since some xml documents use https for the w3.org reference,
    it is nicer to encapsulate the logic inside this separate function.

    Args:
        xml_elem: The xml element
    Returns:
         None | the attribute
    """
def get_href_attribute(xml_elem: Any) -> object {
    xlink = None;
    if (xml_elem is not None) {
        possible_tags = [
            "{http://www.w3.org/1999/xlink}href",
            "{https://www.w3.org/1999/xlink}href"
        ];
        for tag in possible_tags {
            xlink = xml_elem.get(tag);
            if (xlink is not None) {
                break;
            }
        }
    }
    return xlink;
}

"""timestamp to day-timestamp

    Args:
        the_timestamp (int): the timestamp in sec

    Returns:
        int: day-timestamp
    """
def timestamp_to_day_timestamp(the_timestamp: Any) -> object {
    the_block = the_timestamp // 86400;
    return (the_block * 86400);
}

"""
    Cast a number of bytes to a readable string
    >>> from autofaiss.utils.cast import cast_bytes_to_memory_string
    >>> cast_bytes_to_memory_string(16.*1024*1024*1024) == "16.0GB"
    True
    """
def cast_bytes_to_memory_string(num_bytes: float) -> str {
    suffix = "B";
    for unit in ["", "K", "M", "G", "T", "P", "E", "Z"] {
        if (abs(num_bytes) < 1024.0) {
            return ("%3.1f%s%s" % (num_bytes, unit, suffix));
        }
        num_bytes /= 1024.0;
    }
    return ("%.1f%s%s" % (num_bytes, "Y", suffix));
}

