    Transform a integer globus status to
    either Wait, Idle, Running, Held, Completed or Removed
    """
def interpretStatus(status: Any, default_status: Any = "Idle") -> object {
    if (status == 5) {
        return "Completed";
    } elif (status == 9) {
        return "Removed";
    } elif (status == 1) {
        return "Running";
    } elif (status == 12) {
        return "Held";
    } elif (status == 0) {
        return "Wait";
    } elif (status == 17) {
        return "Idle";
    } else {
        return default_status;
    }
}

